CREATE TABLE "public"."steps" (
  "id"                 bigint  GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "lesson_id"          bigint,
  "step_type"          text,
  "sort_order"         integer NOT NULL,
  "linked_headword_id" bigint,
  "content"            jsonb   DEFAULT '{}'::jsonb,
  CONSTRAINT "steps_lesson_id_fkey" FOREIGN KEY (lesson_id) REFERENCES public.lessons(id) ON DELETE CASCADE,
  CONSTRAINT "steps_linked_headword_id_fkey" FOREIGN KEY (linked_headword_id) REFERENCES public.headwords(id),
  CONSTRAINT "steps_pkey" PRIMARY KEY (id),
  CONSTRAINT "steps_step_type_check" CHECK ((step_type = ANY (ARRAY['text'::text, 'video'::text, 'flashcard'::text, 'quiz'::text])))
);

CREATE INDEX idx_steps_lesson_id ON public.steps USING btree (lesson_id);

REVOKE ALL ON SEQUENCE "public"."steps_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."steps_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."steps_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."steps_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."steps_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."steps_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."steps_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."steps_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."steps" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."steps" TO "service_role";

REVOKE ALL ON TABLE "public"."steps" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."steps" TO "postgres";
